import { LoaderResources } from "type";

export const tileNames = ["grass", "objects", "Assets_source"] as const;

export const gameTiles: Record<(typeof tileNames)[number], string> = {
  grass: "assets/locations/grass_32.png",
  objects: "assets/locations/objects.png",
  Assets_source: "assets/locations/mapTiles/Assets_source.png",
};

export const mainResources: LoaderResources = {
  image: [["shadow", ""]],
};
